import { FlatList, View } from 'react-native';
import Header from 'src/components/layout/header';
import Container from 'src/components/styled/atoms/container';
import HMAText from 'src/components/styled/atoms/text';
import HMATextInputMolecule from 'src/components/styled/molecules/input';
import { useTheme } from 'src/hooks/useTheme';
import SeparateEmployee from './seperateEmployee';
import HMADivider from 'src/components/styled/atoms/divider';
import HMAButton from 'src/components/styled/atoms/button';
import { employees } from 'src/hooks/useEmployee';
import {
  findBestMatchingEmployee,
  getAllEmployees,
  getEmployeeById,
} from 'src/database/queries';
import { db } from 'src/database/db';
import { insertEmployees } from 'src/database/insertEmployees';
import { getEmbedding } from 'src/native/FaceEmbed';
import sanitizeBase64 from 'src/function/sanitizeBase64';
import cosineSimilarity from 'src/function/embeddingSimilarity';

export default function ManualMode() {
  const { spacing } = useTheme();
  const fetchEmployee = async () => {
    try {
      console.log('####### START ########', db.transaction);
      const response = await getEmployeeById(1000002);
      // const base64 = `data:image/jpeg;base64,`;
      // const sanitized = sanitizeBase64(base64);
      // const emp = JSON.parse(response?.embedding);
      // const currentEmbedding = await getEmbedding(sanitized);

      console.log('emp:', response);
    } catch (error) {
      console.error(error);
    }
  };

  const pushDummy = () => {
    insertEmployees([
      {
        image: `data:image/jpeg;base64,`,
        id: 1000002,
        name: 'Vijay DEVAR',
      },
    ]);
  };

  const checkEmployee = async () => {
    try {
      console.log('############### STATED #######');
      const base64 = `data:image/jpeg;base64,`;
      const sanitized = sanitizeBase64(base64);
      const currentEmbedding = await getEmbedding(sanitized);
      const result = await findBestMatchingEmployee(currentEmbedding);
      console.log('## RESULT ##', result);
    } catch (error) {
      console.error(error);
    }
  };
  return (
    <Container>
      <HMAButton title="CHECK" onPress={fetchEmployee} />
      <HMAButton title="PUSH DUMMY EMPLOYEE" onPress={pushDummy} />
      <HMAButton title="CHECK DUMMY EMPLOYEE" onPress={checkEmployee} />
    </Container>
  );
  return (
    <Container padding={0} backgroundColor="background">
      <Header title="Manual" />
      <View style={{ paddingHorizontal: spacing.md, flex: 1 }}>
        <HMATextInputMolecule
          placeholder="Search"
          rightIconProps={{
            visible: true,
            name: 'search',
            variant: 'background',
          }}
        />
        <HMADivider />
        <FlatList
          showsVerticalScrollIndicator={false}
          data={new Array(10).fill(0)}
          renderItem={() => <SeparateEmployee />}
        />
      </View>
    </Container>
  );
}
